import assert from 'node:assert/strict';
import { createReadStream, existsSync } from 'node:fs';
import { createServer } from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright';

// Deterministic regression for the sheetClipboard tile cap: the cap fixture
// (compat/sheet/cap.bdf, generated by cap-generate.go) declares a 4,097-tile
// sheet, one tile above the 4,096-tile worker limit. sheetClipboard must
// reject the request with an explicit error before loading any tile object
// part: the fixture's split tile table is inline in the manifest, so a
// rejection without part requests proves the cap check short-circuits the
// per-tile extraction.
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const localBuilds = [
  '_build/js/debug/build/browser/browser.js',
  '_build/js/debug/build/render_worker/render_worker.js',
];
for (const build of localBuilds) {
  if (!existsSync(path.join(root, build))) {
    throw new Error('missing local build ' + build + '; run: moon build browser render_worker --target js');
  }
}

// Only the cap fixture, its split mirror and the local builds are readable;
// every served path is recorded to show which parts were loaded.
const allowed = [
  '/compat/sheet/cap.bdf',
  '/compat/sheet/cap-split/',
  '/_build/js/debug/build/browser/',
  '/_build/js/debug/build/render_worker/',
];
const served = [];
const server = createServer((request, response) => {
  let pathname;
  try { pathname = decodeURIComponent(new URL(request.url, 'http://localhost').pathname); }
  catch { response.writeHead(400).end(); return; }
  if (pathname === '/' || pathname === '/cap-test.html') {
    response.setHeader('Content-Type', 'text/html; charset=utf-8');
    response.end('<!doctype html><meta charset="utf-8"><title>tile cap</title>');
    return;
  }
  served.push(pathname);
  const resolved = path.resolve(root, '.' + pathname);
  if (!allowed.some((prefix) => resolved.startsWith(path.resolve(root, '.' + prefix) + path.sep) || resolved === path.join(root, prefix))) {
    response.writeHead(403).end();
    return;
  }
  const stream = createReadStream(resolved);
  stream.once('error', () => { if (!response.headersSent) response.writeHead(404); response.end(); });
  response.setHeader('Content-Type', pathname.endsWith('.js') ? 'text/javascript' : 'application/octet-stream');
  stream.pipe(response);
});
await new Promise((resolve, reject) => {
  server.once('error', reject);
  server.listen(0, '127.0.0.1', resolve);
});
const base = 'http://127.0.0.1:' + server.address().port;

const browser = await chromium.launch({ headless: true });
try {
  const page = await browser.newPage();
  const browserErrors = [];
  page.on('pageerror', (error) => browserErrors.push(String(error)));
  await page.goto(base + '/cap-test.html', { waitUntil: 'networkidle' });
  const results = await page.evaluate(async () => {
    const moon = await import('/_build/js/debug/build/browser/browser.js');
    const workerUrl = '/_build/js/debug/build/render_worker/render_worker.js';
    const bytes = async (path) => new Uint8Array(await (await fetch(path)).arrayBuffer());
    const attempt = async (makeSource, range) => {
      const client = moon.bdf_render_worker_client(new Worker(workerUrl, { type: 'module' }));
      try {
        const [source] = await makeSource();
        await client.open(source);
        return { ok: true, value: await client.sheetClipboard('cells', range) };
      } catch (error) {
        return { ok: false, name: error.name, message: error.message };
      } finally {
        client.terminate();
      }
    };
    const emptyCell = { row0: 0, col0: 0, row1: 0, col1: 0 };
    const out = [];
    out.push({ name: 'buffer', result: await attempt(async () => [{ kind: 'buffer', buffer: (await bytes('/compat/sheet/cap.bdf')).buffer }], emptyCell) });
    out.push({ name: 'split', result: await attempt(async () => [{ kind: 'split', base: '/compat/sheet/cap-split/' }], emptyCell) });
    return out;
  });
  const label = (name) => {
    const item = results.find((entry) => entry.name === name);
    assert.ok(item, 'result present: ' + name);
    return item.result;
  };
  assert.deepEqual(label('buffer'), {
    ok: false,
    name: 'BdfWorkerError',
    message: 'sheet has too many tiles to copy',
  }, 'buffer source rejects a 4,097-tile sheet');
  assert.deepEqual(label('split'), {
    ok: false,
    name: 'BdfWorkerError',
    message: 'sheet has too many tiles to copy',
  }, 'split source rejects a 4,097-tile sheet');
  // The split tile table is inline in the manifest, so rejecting without
  // any part request proves the cap fires before per-tile loading starts.
  const splitRequests = served.filter((item) => item.startsWith('/compat/sheet/cap-split/'));
  assert.deepEqual(splitRequests, ['/compat/sheet/cap-split/manifest.json'], 'no split part is loaded before the cap rejection');
  const bufferRequests = served.filter((item) => item === '/compat/sheet/cap.bdf');
  assert.deepEqual(bufferRequests.length, 1, 'the buffer fixture is fetched once');
  assert.deepEqual(served.filter((item) => item.includes('/parts/')), [], 'no tile object part is ever loaded');
  assert.deepEqual(browserErrors, [], 'no uncaught page errors');
} finally {
  await browser.close();
  await new Promise((resolve) => server.close(resolve));
}
console.log('tile-cap-clipboard-test: 4,097-tile sheets rejected before loading tile parts');
